#include <cmath>
#include <iostream>
#include <limits>

bool truncar_a_int(double dato, int& destino) {
    if (!std::isfinite(dato)) {
        return false;
    }

    const double minimo =
        static_cast<double>(std::numeric_limits<int>::lowest());
    const double maximo =
        static_cast<double>(std::numeric_limits<int>::max());
    // Este control descarta tambien algunas fracciones convertibles.
    if (dato < minimo || dato > maximo) {
        return false;
    }

    destino = static_cast<int>(dato);
    return true;
}

int main() {
    if (std::numeric_limits<int>::radix != 2
        || std::numeric_limits<int>::digits != 31
        || std::numeric_limits<double>::radix != 2
        || std::numeric_limits<double>::digits != 53) {
        return 2;
    }

    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    const double minimo =
        static_cast<double>(std::numeric_limits<int>::lowest());
    const double maximo =
        static_cast<double>(std::numeric_limits<int>::max());
    double dato = 0.0;
    switch (caso) {
    case 1: dato = maximo + 0.5; break;
    case 2: dato = minimo - 0.5; break;
    case 3: dato = maximo + 1.0; break;
    case 4: dato = minimo - 1.0; break;
    case 5: dato = -3.75; break;
    case 6: dato = -0.75; break;
    case 7: dato = std::numeric_limits<double>::infinity(); break;
    case 8: dato = std::numeric_limits<double>::quiet_NaN(); break;
    case 9: dato = -std::numeric_limits<double>::infinity(); break;
    case 10: dato = 0.0; break;
    default: return 1;
    }

    int destino = 17;
    const bool aceptado = truncar_a_int(dato, destino);
    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Destino=" << destino << '\n';
    return 0;
}

