    if (truncado < minimo || truncado > maximo) {
        return false;
    }

    destino = static_cast<int>(truncado);
    return true;
}
bool conservar_a_int(double dato, int& destino) {
    // Este inicio puede cambiar destino antes de decidir el rechazo.
    if (!truncar_a_int(dato, destino)) {
        return false;
    }
    return static_cast<double>(destino) == dato;
}

int main() {
    if (std::numeric_limits<int>::radix != 2
